<?php
declare(strict_types=1);
final class CalculationEngineV100{public const VERSION='1.0.0';public static function calculate(array $i):array{self::v($i);$months=$i['horizon_years']*12;$assets=$i['assets']??[$i];$o=[];$t=['nominal_value'=>0.,'real_value'=>0.,'cumulative_contributions'=>0.,'cumulative_entry_fees'=>0.,'cumulative_ongoing_fees'=>0.,'cumulative_fixed_fees'=>0.,'cumulative_total_fees'=>0.,'net_gain'=>0.];foreach($assets as$n=>$a){$r=self::a($a,$months,(float)$i['inflation_rate']);$id=$a['id']??'asset_'.($n+1);$o[$id]=$r;foreach($t as$k=>$_)$t[$k]+=$r[$k];}$t['assets']=$o;$t['engine_version']=self::VERSION;$t['success']=true;$t['calculation_status']='OK';return$t;}private static function a(array$a,int$m,float$inf):array{foreach(['initial_contribution','monthly_contribution','annual_return','entry_fee_initial_pct','entry_fee_monthly_pct','ongoing_fee_pct_pa','fixed_fee_monthly']as$k)if(!array_key_exists($k,$a)||!is_numeric($a[$k])||!is_finite((float)$a[$k]))throw new InvalidArgumentException('NON_FINITE_NUMBER:'.$k);$x=(float)$a['initial_contribution'];$mo=(float)$a['monthly_contribution'];$ar=(float)$a['annual_return'];$ei=(float)$a['entry_fee_initial_pct'];$em=(float)$a['entry_fee_monthly_pct'];$og=(float)$a['ongoing_fee_pct_pa'];$fx=(float)$a['fixed_fee_monthly'];if($x<0)throw new InvalidArgumentException('INITIAL_CONTRIBUTION_NEGATIVE');if($mo<0)throw new InvalidArgumentException('MONTHLY_CONTRIBUTION_NEGATIVE');if($ar<=-1)throw new InvalidArgumentException('ANNUAL_RETURN_OUT_OF_RANGE');if($ei<0||$ei>1)throw new InvalidArgumentException('ENTRY_FEE_INITIAL_OUT_OF_RANGE');if($em<0||$em>1)throw new InvalidArgumentException('ENTRY_FEE_MONTHLY_OUT_OF_RANGE');if($og<0||$og>=1)throw new InvalidArgumentException('ONGOING_FEE_OUT_OF_RANGE');if($fx<0)throw new InvalidArgumentException('FIXED_FEE_NEGATIVE');$entry=$x*$ei;$b=$x-$entry;$of=0.;$ff=0.;$mr=pow(1+$ar,1/12)-1;$mf=pow(1-$og,1/12);$c=$x;for($j=0;$j<$m;$j++){$b*=1+$mr;$before=$b;$b*=$mf;$of+=max(0,$before-$b);$ch=min($fx,$b);$b-=$ch;$ff+=$ch;$ef=$mo*$em;$entry+=$ef;$b+=max(0,$mo-$ef);$c+=$mo;}$total=$entry+$of+$ff;return['nominal_value'=>$b,'real_value'=>$b/pow(1+$inf,$m/12),'cumulative_contributions'=>$c,'cumulative_entry_fees'=>$entry,'cumulative_ongoing_fees'=>$of,'cumulative_fixed_fees'=>$ff,'cumulative_total_fees'=>$total,'net_gain'=>$b-$c];}private static function v(array$i):void{$y=$i['horizon_years']??0;$f=$i['inflation_rate']??-1;if(!is_int($y)||$y<1||$y>100)throw new InvalidArgumentException('HORIZON_OUT_OF_RANGE');if(!is_numeric($f)||!is_finite((float)$f)||(float)$f<=-1)throw new InvalidArgumentException('INFLATION_OUT_OF_RANGE');if(isset($i['snapshot_years']))foreach($i['snapshot_years']as$s)if(!is_int($s)||$s<1||$s>$y)throw new InvalidArgumentException('SNAPSHOT_OUT_OF_RANGE');if(isset($i['assets'])){$seen=[];foreach($i['assets']as$a){$id=(string)($a['id']??'');if($id===''||isset($seen[$id]))throw new InvalidArgumentException($id===''?'ASSET_ID_REQUIRED':'DUPLICATE_ASSET_ID');$seen[$id]=1;}}}}
